#include <iostream>
#include <fstream>

using namespace std; 

int main() 
{
    string word = "hello"; 
    int count = 0; 

    // Open the file 
    ifstream myfile("file.txt"); 

    // Read the file line by line 
    string line; 
    while (getline(myfile, line)) 
    { 
        // Count the occurences of the word 
        count += line.find(word) != string::npos; 
    } 

    // Output the result 
    cout << "Word: " << word 
        << "\tNumber of occurences: " << count; 

    return 0; 
}

