def longest_common_subseq(s1, s2): 
    # Initialize dp as 0 for both strings 
    dp = [0 for _ in range(len(s1))]
    dp[i] = max(dp[i-1] for _ in range(len(s2)))

    # Find the LCS for s1 and s2 from 0 to i-1
    for j in range(1, len(s1)+1): 
        dp[j] = max(dp[j-1] or 0, s1[j-1] + 1 + dp[j-i-1] 
                    if s1[j-1] == s2[i-1] else 0) 

    # Return the LCS from i to len(s2) 
    return s1[i:] + dp[i:]

