class Queue:
    def __init__(self):
        self.items = [] # Stack of items
        self.front = None
        self.back = None

    def enqueue(self, item):
        if self.back is None:
            self.items.append(item) # Add item to the back of the queue
        else:
            self.push(item, self.back) # Push item at back of queue
            self.back = self.items.pop() # Pop last item in queue and make it the new back pointer

    def dequeue(self):
        if self.front is None:
            raise QueueEmptyError("The queue is empty")
        return self.items.pop(self.front) # Pop the item from the front of the queue

    def push(self, item, back):
        if back is None:
            self.items.append(item) # Append item to the back of the queue
        else:
            self.items[back] = item # Push item at position back in queue
            self.back = back # Set back pointer to last item in queue
        return self.back # Return new back pointer

    def pop(self):
        if self.front is None:
            raise QueueEmptyError("The queue is empty")
        return self.items.pop(self.front) # Pop the item from the front of the queue

    def empty(self):
        if self.front is None and self.back is None:
            return False
        else:
            return True

    def __str__(self):
        if self.front is not None:
            output = "Queue: "
            output += "\n".join([str(i) for i in self.items])
            output += "\nBack: " + str(self.back)
            output += "\nFront: " + str(self.front)
            return output
        else:
            return "Empty Queue"

